static <T> MyOptional<T> of(T t) {
            Preconditions.checkNotNull(t);
            return new MyOptional<T>(t);
        }

static <T> MyOptional<T> of(T t) {
            Preconditions.checkNotNull(t);
            return new MyOptional<T>(t);
        }

@SuppressWarnings("unchecked")
        static <T> MyOptional<T> empty() {
            return (MyOptional<T>) EMPTY;
        }

boolean isPresent() {
            return t != null;
        }

T get() {
            Preconditions.checkNotNull(t);
            return t;
        }

@SuppressWarnings("unchecked")
        static <T> BiFunction<List<T>, MyOptional<T>, List<T>> addIfPresent() {
            return (BiFunction<List<T>, MyOptional<T>, List<T>>) (BiFunction<?, ?, ?>) ADD;
        }

@SuppressWarnings("unchecked")
        static <T> Predicate<List<T>> listHasElements() {
            return (Predicate<List<T>>) (Predicate<?>) LIST_HAS_ELEMENTS;
        }

@SuppressWarnings("unchecked")
        static <T> Callable<List<T>> factory() {
            return (Callable<List<T>>) (Callable<?>) INSTANCE;
        }

public static <T, R> FlowableTransformer<T, R> collectWhile(final Callable<R> collectionFactory,
            final BiFunction<? super R, ? super T, ? extends R> add, final BiPredicate<? super R, ? super T> condition,
            final boolean emitRemainder) {
        return new FlowableTransformer<T, R>() {

            @Override
            public Publisher<R> apply(Flowable<T> source) {
                return new FlowableCollectWhile<T, R>(source, collectionFactory, add, condition, emitRemainder);
            }
        };
    }

public static <T, R> FlowableTransformer<T, R> collectWhile(final Callable<R> collectionFactory,
            final BiFunction<? super R, ? super T, ? extends R> add, final BiPredicate<? super R, ? super T> condition,
            final boolean emitRemainder) {
        return new FlowableTransformer<T, R>() {

            @Override
            public Publisher<R> apply(Flowable<T> source) {
                return new FlowableCollectWhile<T, R>(source, collectionFactory, add, condition, emitRemainder);
            }
        };
    }

public static <T> FlowableTransformer<T, T> insert(
            final Function<? super T, ? extends Maybe<? extends T>> valueToInsert) {
        return new FlowableTransformer<T, T>() {

            @Override
            public Publisher<T> apply(Flowable<T> source) {
                return new FlowableInsertMaybe<T>(source, valueToInsert);
            }

        };
    }

public static <T> FlowableTransformer<T, List<T>> buffer(final int maxSize, final long duration,
            final TimeUnit unit) {
        return buffer(maxSize, Functions.constant(duration), unit);
    }

public static <T> FlowableTransformer<T, List<T>> buffer(final int maxSize, final long duration,
            final TimeUnit unit) {
        return buffer(maxSize, Functions.constant(duration), unit);
    }

public static <T> FlowableTransformer<T, List<T>> buffer(final int maxSize, final long duration,
            final TimeUnit unit) {
        return buffer(maxSize, Functions.constant(duration), unit);
    }

public static <T> Function<Object, T> constant(final T value) {
        return new Function<Object, T>() {

            @Override
            public T apply(Object t) throws Exception {
                return value;
            }
        };
    }

private Functions() {
        // prevent instantiation
    }

@Override
            public T apply(Object t) throws Exception {
                return value;
            }

public FlowableInsertTimeout(Flowable<T> source, Function<? super T, ? extends Long> timeout, TimeUnit unit,
            Function<? super T, ? extends T> value, Scheduler scheduler) {
        Preconditions.checkNotNull(timeout, "timeout cannot be null");
        Preconditions.checkNotNull(unit, "unit cannot be null");
        Preconditions.checkNotNull(value, "value cannot be null");
        Preconditions.checkNotNull(scheduler, "scheduler cannot be null");
        this.source = source;
        this.timeout = timeout;
        this.unit = unit;
        this.value = value;
        this.scheduler = scheduler;
    }

@Override
    protected void subscribeActual(Subscriber<? super T> downstream) {
        source.subscribe(new InsertTimeoutSubscriber<T>(downstream, timeout, unit, value, scheduler));
    }

public FlowableCollectWhile(Flowable<T> source, Callable<R> collectionFactory,
            BiFunction<? super R, ? super T, ? extends R> add,
            BiPredicate<? super R, ? super T> condition, boolean emitRemainder) {
        super();
        this.source = source;
        this.collectionFactory = collectionFactory;
        this.add = add;
        this.condition = condition;
        this.emitRemainder = emitRemainder;
    }

@Override
    protected void subscribeActual(Subscriber<? super R> child) {
        CollectWhileSubscriber<T, R> subscriber = new CollectWhileSubscriber<T, R>(
                collectionFactory, add, condition, child, emitRemainder);
        source.subscribe(subscriber);
    }

public FlowableInsertTimeout(Flowable<T> source, Function<? super T, ? extends Long> timeout, TimeUnit unit,
            Function<? super T, ? extends T> value, Scheduler scheduler) {
        Preconditions.checkNotNull(timeout, "timeout cannot be null");
        Preconditions.checkNotNull(unit, "unit cannot be null");
        Preconditions.checkNotNull(value, "value cannot be null");
        Preconditions.checkNotNull(scheduler, "scheduler cannot be null");
        this.source = source;
        this.timeout = timeout;
        this.unit = unit;
        this.value = value;
        this.scheduler = scheduler;
    }

@Override
        public void onSubscribe(Subscription upstream) {
            if (SubscriptionHelper.validate(this.upstream, upstream)) {
                this.upstream = upstream;
                downstream.onSubscribe(this);
            }
        }

@Override
        public void onNext(final T t) {
            if (finished) {
                return;
            }
            queue.offer(t);
            final long waitTime;
            try {
                waitTime = timeout.apply(t);
            } catch (Throwable e) {
                Exceptions.throwIfFatal(e);
                // we cancel upstream ourselves because the
                // error did not originate from source
                upstream.cancel();
                onError(e);
                return;
            }
            TimeoutAction<T> action = new TimeoutAction<T>(this, t);
            Disposable d = worker.schedule(action, waitTime, unit);
            DisposableHelper.set(scheduled, d);
            drain();
        }

@Override
        public void onComplete() {
            if (finished) {
                return;
            }
            finished = true;
            if (terminated.compareAndSet(null, TERMINATED)) {
                dispose();
                drain();
            }
        }

private void drain() {
            if (getAndIncrement() != 0) {
                return;
            }
            // note that this drain loop does not shortcut errors
            int missed = 1;
            while (true) {
                long r = requested.get();
                long e = 0;
                while (e != r) {
                    if (cancelled) {
                        dispose();
                        queue.clear();
                        return;
                    }
                    Object d = terminated.get();
                    T t = queue.poll();
                    if (t == null) {
                        if (d != null) {
                            // d will be either TERMINATED or a Throwable
                            if (d == TERMINATED) {
                                // don't need to dispose scheduled because already done in
                                // onComplete
                                downstream.onComplete();
                            } else {
                                // clear the exception so can be gc'd
                                // setting the value to TERMINATED just prevents it getting set again in a race
                                // because the other setters which use CAS assume initial value of null
                                terminated.set(TERMINATED);
                                dispose();
                                downstream.onError((Throwable) d);
                            }
                            return;
                        } else {
                            // nothing to emit and not done
                            break;
                        }
                    } else {
                        downstream.onNext(t);
                        e++;
                    }
                }
                if (e != 0L && r != Long.MAX_VALUE) {
                    requested.addAndGet(-e);
                }
                missed = addAndGet(-missed);
                if (missed == 0) {
                    return;
                }
            }
        }

@Override
        public void request(long n) {
            if (SubscriptionHelper.validate(n)) {
                BackpressureHelper.add(requested, n);
                // modify request to upstream to account for inserted values
                // use a CAS loop because request can be called from any thread
                while (true) {
                    long ins = inserted.get();
                    long d = Math.min(ins, n);
                    if (inserted.compareAndSet(ins, ins - d)) {
                        if (n - d > 0) {
                            upstream.request(n - d);
                        }
                        break;
                    }
                }
                drain();
            }
        }

private void dispose() {
            DisposableHelper.dispose(scheduled);
            worker.dispose();
        }

void insert(T t) {
            inserted.incrementAndGet();
            queue.offer(t);
            drain();
        }

T calculateValueToInsert(T t) throws Exception {
            return value.apply(t);
        }

public FlowableCollectWhile(Flowable<T> source, Callable<R> collectionFactory,
            BiFunction<? super R, ? super T, ? extends R> add,
            BiPredicate<? super R, ? super T> condition, boolean emitRemainder) {
        super();
        this.source = source;
        this.collectionFactory = collectionFactory;
        this.add = add;
        this.condition = condition;
        this.emitRemainder = emitRemainder;
    }

@Override
        public void onSubscribe(Subscription parent) {
            if (SubscriptionHelper.validate(this.parent, parent)) {
                this.parent = parent;
                child.onSubscribe(this);
            }
        }

@Override
        public void onNext(T t) {
            // this path taken by upstream if not enabled to call `tryOnNext`
            if (!tryOnNext(t)) {
                parent.request(1);
            }
        }

@Override
        public boolean tryOnNext(T t) {
            if (done) {
                return true;
            }
            if (collection == null && !collectionCreated()) {
                return true;
            }
            boolean collect;
            try {
                collect = condition.test(collection, t);
            } catch (Throwable e) {
                Exceptions.throwIfFatal(e);
                onError(e);
                return true;
            }
            if (!collect) {
                queue.offer(collection);
                if (!collectionCreated()) {
                    return true;
                }
            }
            try {
                collection = add.apply(collection, t);
                if (collection == null) {
                    throw new NullPointerException("add function should not return null");
                }
            } catch (Throwable e) {
                Exceptions.throwIfFatal(e);
                onError(e);
                return true;
            }
            drain();
            return !collect;
        }

public boolean collectionCreated() {
            try {
                collection = collectionFactory.call();
                if (collection == null) {
                    throw new NullPointerException("collectionFactory should not return null");
                }
                return true;
            } catch (Throwable e) {
                Exceptions.throwIfFatal(e);
                onError(e);
                return false;
            }
        }

@Override
        public void onComplete() {
            if (done) {
                return;
            }
            R col = collection;
            if (col != null) {
                collection = null;
                // ensure that the remainder is emitted
                // if configured to
                if (emitRemainder) {
                    queue.offer(col);
                }
            }
            done = true;
            drain();
        }

private void drain() {
            if (getAndIncrement() == 0) {
                int missed = 1;
                while (true) {
                    long r = requested.get();
                    long e = 0;
                    while (e != r) {
                        if (cancelled) {
                            queue.clear();
                            return;
                        }
                        //must read `done` before polling queue
                        boolean d = done;
                        R c = queue.poll();
                        if (c == null) {
                            if (d) {
                                // `error` must be read AFTER `done` for
                                // full visibility
                                Throwable err = error;
                                if (err != null) {
                                    error = null;
                                    child.onError(err);
                                } else {
                                    child.onComplete();
                                }
                                return;
                            } else {
                                // nothing to emit and not done
                                break;
                            }
                        } else {
                            child.onNext(c);
                            e++;
                        }
                    }
                    if (e != 0L && r != Long.MAX_VALUE) {
                        requested.addAndGet(-e);
                    }
                    missed = addAndGet(-missed);
                    if (missed == 0) {
                        return;
                    }
                }
            }

        }

@Override
        public void request(long n) {
            if (SubscriptionHelper.validate(n)) {
                BackpressureHelper.add(requested, n);
                parent.request(n);
                drain();
            }
        }

public FlowableInsertTimeout(Flowable<T> source, Function<? super T, ? extends Long> timeout, TimeUnit unit,
            Function<? super T, ? extends T> value, Scheduler scheduler) {
        Preconditions.checkNotNull(timeout, "timeout cannot be null");
        Preconditions.checkNotNull(unit, "unit cannot be null");
        Preconditions.checkNotNull(value, "value cannot be null");
        Preconditions.checkNotNull(scheduler, "scheduler cannot be null");
        this.source = source;
        this.timeout = timeout;
        this.unit = unit;
        this.value = value;
        this.scheduler = scheduler;
    }

@Override
        public void run() {
            final T v;
            try {
                v = subscriber.calculateValueToInsert(t);
            } catch (Throwable e) {
                subscriber.insertError(e);
                return;
            }
            subscriber.insert(v);
        }
